    @MainActor private static var cache: [String: NSImage] = [:]

    /// The icon as a template image (it takes the text colour); nil for a name the table does not have.
    @MainActor static func image(_ name: String) -> NSImage? {
        if let i = cache[name] { return i }
        guard let s = svg[name], let i = NSImage(data: Data(s.utf8)) else { return nil }
        i.isTemplate = true
        cache[name] = i
        return i
    }
